-- Additive customer calendar metadata. Generated by scripts/compile-calendar-migration.mjs.
create or replace function public.catera_v1_read(resource text,params jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();result jsonb;seller_id uuid;dt date;lim int:=least(greatest(coalesce((params->>'limit')::int,50),1),100);offst int:=greatest(coalesce((params->>'offset')::int,0),0);
begin
 if resource='catalog' then
  select jsonb_build_object('items',coalesce(jsonb_agg(x.o),'[]'),'nextCursor',case when count(*)=lim then (offst+lim)::text else null end) into result from (select v1.offer(p) o from v1.packages p join v1.caterers c on c.id=p.caterer_id where p.status='published' and c.status='approved' order by case when c.areas @> array[params->>'area'] then 0 else 1 end,p.slug limit lim offset offst)x;return result;
 elsif resource='reviews' then return coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('customer',p.name)) from v1.reviews r join v1.profiles p on p.id=r.user_id where r.package_id=(params->>'id')::uuid and not hidden),'[]');
 end if;
 if u is null then raise exception 'UNAUTHORIZED';end if;
 if resource='actor' then return (select to_jsonb(p)||jsonb_build_object('catererId',(select caterer_id from v1.staff where user_id=u limit 1)) from v1.profiles p where p.id=u);
 elsif resource='availability' then return v1.availability(u,params);
 elsif resource='quote' then return v1.quote(u,params);
 elsif resource='checkout' then return (select to_jsonb(x) from v1.checkouts x where id=(params->>'id')::uuid and user_id=u);
 elsif resource='customer' then
  return (case when params->>'calendarMeta'='true' then jsonb_build_object('calendarMeta',(
    select jsonb_build_object('nextDeliveryDate',min(d.service_date),'lastUpcomingDeliveryDate',max(d.service_date))
    from v1.delivery_days d join v1.subscriptions s on s.id=d.subscription_id
    where s.user_id=u and d.service_date >= (current_timestamp at time zone 'Asia/Jakarta')::date
      and d.status not in ('delivered','cancelled')
      and exists (select 1 from v1.fulfillments f where f.day_id=d.id and f.status not in ('delivered','cancelled'))
  )) else '{}'::jsonb end) || jsonb_build_object('subscriptions',coalesce((select jsonb_agg(to_jsonb(s)||jsonb_build_object('remaining',(select count(*) from v1.delivery_days d where d.subscription_id=s.id and d.status not in('delivered','cancelled')))) from v1.subscriptions s where s.user_id=u),'[]'),'deliveries',coalesce((select jsonb_agg(v1.delivery(d) order by d.service_date) from v1.delivery_days d join v1.subscriptions s on s.id=d.subscription_id where s.user_id=u and ((params->>'deliveryId' is not null and d.id=(params->>'deliveryId')::uuid) or (params->>'deliveryId' is null and d.service_date between coalesce((params->>'from')::date,current_date-7) and coalesce((params->>'to')::date,current_date+60)))),'[]'),'addresses',coalesce((select jsonb_agg(to_jsonb(a)-'user_id') from v1.addresses a where user_id=u),'[]'),'notifications',coalesce((select jsonb_agg(to_jsonb(n)) from (select * from v1.notifications where user_id=u order by created_at desc limit 50)n),'[]'),'cases',coalesce((select jsonb_agg(to_jsonb(s)) from v1.support_cases s where user_id=u),'[]'));
 elsif resource='conversations' then
  return coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('caterer',k.name,'customer',p.name,'messages',coalesce((select jsonb_agg(to_jsonb(m) order by m.created_at) from (select * from v1.messages where conversation_id=c.id order by created_at desc limit 100)m),'[]'))) from v1.conversations c join v1.caterers k on k.id=c.caterer_id join v1.profiles p on p.id=c.customer_id where c.customer_id=u or v1.is_staff(u,c.caterer_id)),'[]');
 elsif resource='seller' then
  seller_id:=(params->>'id')::uuid;dt:=coalesce((params->>'date')::date,current_date);if not v1.is_staff(u,seller_id) then raise exception 'FORBIDDEN';end if;
  return jsonb_build_object('caterer',(select to_jsonb(k)||jsonb_build_object('area',k.areas) from v1.caterers k where id=seller_id),'offers',coalesce((select jsonb_agg(v1.offer(p)) from v1.packages p where caterer_id=seller_id),'[]'),'dishes',coalesce((select jsonb_agg(v1.library_dish(d) order by d.details->>'name',d.id) from v1.dishes d where d.caterer_id=seller_id),'[]'),'contentRevisions',v1.seller_content_revisions(seller_id),'datedMenus',coalesce((select jsonb_agg(to_jsonb(m)) from v1.menus m join v1.packages p on p.id=m.package_id where p.caterer_id=seller_id and m.service_date=dt),'[]'),'deliveries',coalesce((select jsonb_agg(v1.delivery(d)) from v1.delivery_days d join v1.subscriptions s on s.id=d.subscription_id join v1.packages p on p.id=s.package_id where p.caterer_id=seller_id and d.service_date=dt),'[]'),'cases',coalesce((select jsonb_agg(to_jsonb(x)) from v1.support_cases x where caterer_id=seller_id),'[]'),'customers',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'source',r.source)) from v1.relationships r join v1.profiles p on p.id=r.user_id where r.caterer_id=seller_id),'[]'),'transactions',case when v1.is_staff(u,seller_id,true) then coalesce((select jsonb_agg(to_jsonb(x)) from (select ch.* from v1.checkouts ch join v1.packages p on p.id=ch.package_id where p.caterer_id=seller_id order by created_at desc limit 100)x),'[]') else '[]'::jsonb end,'staff',case when v1.is_staff(u,seller_id,true) then coalesce((select jsonb_agg(to_jsonb(s)||jsonb_build_object('name',p.name)) from v1.staff s join v1.profiles p on p.id=s.user_id where s.caterer_id=seller_id),'[]') else '[]'::jsonb end,'payouts',case when v1.is_staff(u,seller_id,true) then coalesce((select jsonb_agg(to_jsonb(p)) from v1.payouts p where caterer_id=seller_id),'[]') else '[]'::jsonb end);
 elsif resource='admin' then
  if not v1.is_admin(u) then raise exception 'FORBIDDEN';end if;
  return jsonb_build_object('caterers',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('area',c.areas,'offers',coalesce((select jsonb_agg(v1.offer(pack)) from v1.packages pack where pack.caterer_id=c.id),'[]'))) from v1.caterers c),'[]'),'cases',coalesce((select jsonb_agg(to_jsonb(s)) from v1.support_cases s),'[]'),'transactions',coalesce((select jsonb_agg(to_jsonb(c)) from (select * from v1.checkouts order by created_at desc limit 100)c),'[]'),'audit',coalesce((select jsonb_agg(to_jsonb(a)) from (select * from v1.audit order by created_at desc limit 100)a),'[]'),'promotions',coalesce((select jsonb_agg(to_jsonb(p)) from v1.promotions p),'[]'),'payouts',coalesce((select jsonb_agg(to_jsonb(p)) from v1.payouts p),'[]'),'refunds',coalesce((select jsonb_agg(to_jsonb(r)) from v1.refunds r),'[]'),'reviews',coalesce((select jsonb_agg(to_jsonb(r)) from v1.reviews r),'[]'));
 end if;raise exception 'NOT_FOUND';
end $$;
